class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def partition(self, head, x):
        less, greater = [], []
        while head:
            if head.val < x:
                less.append(head.val)
            else:
                greater.append(head.val)
            head = head.next

        dummy = ListNode()
        tail = dummy
        for value in less + greater:
            tail.next = ListNode(value)
            tail = tail.next
        return dummy.next

